local function dumpInstance(instance, log, indent)
    indent = indent or S(21)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(130) .. child.Name .. S(45)
        if child:IsA(S(133)) then
            line = line .. string.format(
                S(179),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(142)) then
            line = line .. string.format(S(173), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(57)) or child:IsA(S(11)) then
            line = line .. S(152)
        end
        log(line)
        dumpInstance(child, log, indent .. S(183))
    end
end
return dumpInstance
end
